using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.USR.TiposMascota;using GraphApi.Services.USR.TiposMascota;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.USR.TiposMascota{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de TiposMascotas: creación, actualización y eliminación.")]    public class TiposMascotaMutation    {        [Authorize]        [GraphQLName("createTiposMascota")]        [GraphQLDescription("Crea un nuevo TiposMascota usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadTiposMascota> CreateTiposMascotaAsync(            [GraphQLDescription("Datos necesarios para crear el TiposMascota.")]            clCreateTiposMascota objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de TiposMascota.")]            ITiposMascotaService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateTiposMascota(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateTiposMascota")]        [GraphQLDescription("Actualiza los campos especificados de un TiposMascota existente.")]        public async Task<clReadTiposMascota?> UpdateTiposMascotaAsync(            [GraphQLDescription("Datos del TiposMascota a actualizar.")]            clUpdateTiposMascota objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de TiposMascota.")]            ITiposMascotaService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateTiposMascota(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteTiposMascota")]        [GraphQLDescription("Elimina un TiposMascota por su ID.")]        public async Task<bool> delTiposMascotaAsync(            [GraphQLDescription("ID del TiposMascota a eliminar.")]            int nTiposMascotaID,            [Service]            [GraphQLDescription("Servicio para operaciones de TiposMascota.")]            ITiposMascotaService objService        )        {            return await objService.DeleteTiposMascota(nTiposMascotaID);        }    }}